/// <summary>
/// CB167_PerformStockReservation
/// This is a data contract class for reserve event orders batch job.
/// </summary>
[  DataContract
 , SysOperationContractProcessing(classStr(METReserveEventOrdersUIBuilder))
 , SysOperationAlwaysInitialize
]
class METReserveEventOrdersContract extends METSysOperationTaskDataContract implements SysOperationInitializable
{
    METSalesEventId  eventId;
    InventLocationId warehouse;
    TransDate        releaseDate;
    METPOLink        poLink;
    guid             topPickingProcessId;

}

Method.Source:
/// <summary>
/// Gets and sets event Id.
/// </summary>
/// <param name = "_eventId">event Id.</param>
/// <returns>event Id.</returns>
[DataMember]
public METSalesEventId parmEventId(METSalesEventId _eventId = eventId)
{
    eventId = _eventId;
    return eventId;
}

/// <summary>
///  Gets and sets warehouse.
/// </summary>
/// <param name = "_warehouse">warehouse.</param>
/// <returns>warehouse.</returns>
[DataMember]
public InventLocationId parmWarehouse(InventLocationId _warehouse = warehouse)
{
    warehouse = _warehouse;
    return warehouse;
}

/// <summary>
/// Gets and sets release date.
/// </summary>
/// <param name = "_releaseDate"> release date.</param>
/// <returns> release date.</returns>
[DataMember, SysOperationLabel("@MET:METReleaseDate")]
public TransDate parmReleaseDate(TransDate _releaseDate = releaseDate)
{
    releaseDate = _releaseDate;
    return releaseDate;
}

[DataMember]
public METPOLink parmPOLink(METPOLink _poLink = poLink)
{
    poLink = _poLink;
    return poLink;
}

/// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibility(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;
    return topPickingProcessId;
}

/// <summary>
/// Initiazes data variables.
/// </summary>
public void initialize()
{
    releaseDate = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
}
